{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
let seenBallot = false
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (cands !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const set = new Set()
    for (const name of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (set.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      set.add(name)
    }
    cands = set
  } else if (t[0] === 'ballot') {
    seenBallot = true
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands || !cands.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (cands === null) fail('error: no candidates')

const continuing = new Set(cands)
const history = [] // Map per round
const out = []
let nRounds = 0
let result = 'no winner'
for (;;) {
  nRounds++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  history.push(counts)
  const order = [...counts.keys()].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    if (d !== 0n) return d > 0n ? 1 : -1
    return a < b ? -1 : a > b ? 1 : 0
  })
  let line = `round ${nRounds}: ` + order.map((c) => `${c}=${counts.get(c)}`).join(' ')
  line += ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const win = order.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) {
    result = `winner ${win}`
    break
  }
  let min = counts.get(order[order.length - 1])
  let set = order.filter((c) => counts.get(c) === min)
  let r = 0
  while (set.length > 1 && r < history.length) {
    const vals = set.map((c) => history[r].get(c))
    const m = vals.reduce((a, b) => (a < b ? a : b))
    if (vals.some((v) => v !== m)) {
      set = set.filter((c) => history[r].get(c) === m)
      r = 0
    } else r++
  }
  const elim = set.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
process.stdout.write(mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${nRounds}\n${result}\n`)
EOF
node --test test/*.test.js 2>&1 | tail -8","description":"Write CLI and run tests"}

