{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const MODES = ['merge', 'merge2', 'regions']

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const sides = { mine, theirs }
  const all = [...changes(base, mine, 'mine'), ...changes(base, theirs, 'theirs')]
  all.sort((a, b) => a.bs - b.bs)

  const out = []
  const reg = []
  let conflict = false
  let pos = 0
  const stable = end => {
    if (end > pos) {
      out.push(...base.slice(pos, end))
      reg.push(`stable ${end - pos}`)
    }
  }
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    const baseL = base.slice(rs, re)
    const repl = who => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseL
      const first = cs.reduce((a, c) => (c.bs < a.bs ? c : a))
      const last = cs.reduce((a, c) => (c.be > a.be ? c : a))
      const s = first.ss - (first.bs - rs)
      const e = last.se + (re - last.be)
      return sides[who].slice(s, e)
    }
    const mL = repl('mine'), tL = repl('theirs')
    const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
    if (eq(mL, tL)) {
      out.push(...mL); reg.push(`both ${mL.length}`)
    } else if (eq(mL, baseL)) {
      out.push(...tL); reg.push(`theirs ${tL.length}`)
    } else if (eq(tL, baseL)) {
      out.push(...mL); reg.push(`mine ${mL.length}`)
    } else {
      conflict = true
      out.push('<<<<<<< mine', ...mL)
      if (mode === 'merge') out.push('||||||| base', ...baseL)
      out.push('=======', ...tL, '>>>>>>> theirs')
      reg.push(`conflict mine=${mL.length} base=${baseL.length} theirs=${tL.length}`)
    }
    pos = re
  }
  stable(base.length)
  const res = mode === 'regions' ? reg : out
  process.stdout.write(res.map(l => `${l}\n`).join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
EOF
