      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === q) { this.i++; return out }
      if (q === '"' && c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(m, e)) { out += m[e]; this.i += 2; continue }
        if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 6; continue
        }
        fail(`invalid escape \\${e}`)
      }
      out += c; this.i++
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (isNameCh(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') { this.i++; this.ws(); parts.push(this.name()) } else { this.i = save; return parts }
