      if (n === undefined) { n = new Arr(true); t.map.set(last, n) }
      if (!(n instanceof Arr && n.aot)) fail(`${p} is not an array of tables`)
      const nt = new Table(); nt.defined = true
      n.items.push(nt)
      return { table: nt, path }
    }
    if (n === undefined) { n = new Table(); t.map.set(last, n) }
    if (!(n instanceof Table)) fail(`${p} is not a table`)
    if (n.defined) fail(`table ${p} is defined twice`)
    n.defined = true
    return { table: n, path }
  }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = { table: root, path: [] }
  lines.forEach((line, idx) => {
    try {
      const p = new LineParser(line)
      p.ws()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') { cur = p.header(root); return }
