const cost = new Map()
const depLines = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})

const deps = new Map()
for (const name of cost.keys()) deps.set(name, new Set())
for (const w of depLines) {
  for (const name of w) if (!cost.has(name)) fail(`error: unknown task ${name}`)
  for (const d of w.slice(1)) deps.get(w[0]).add(d)
}
const names = [...cost.keys()].sort()
const sortedDeps = new Map(names.map((n) => [n, [...deps.get(n)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of sortedDeps.get(n)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(n, 2)
  }
  for (const n of names) if (!state.get(n)) visit(n)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (n) => {
  if (finish.has(n)) return
  let s = 0n
  let d = 0
  for (const x of sortedDeps.get(n)) {
    calc(x)
    if (finish.get(x) > s) s = finish.get(x)
    if (depth.get(x) + 1 > d) d = depth.get(x) + 1
  }
  start.set(n, s)
  finish.set(n, s + cost.get(n))
  depth.set(n, d)
}
names.forEach(calc)
let total = 0n
for (const f of finish.values()) if (f > total) total = f

const out = []
if (mode === 'waves') {
  const byDepth = []
  for (const n of names) (byDepth[depth.get(n)] ??= []).push(n)
  byDepth.forEach((g, k) => out.push(`wave ${k}: ${g.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const n of names) out.push(`${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
  out.push(`total ${total}`)
} else {
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of sortedDeps.get(n)) dependents.get(d).push(n)
  const prio = new Map()
  const pr = (n) => {
    if (prio.has(n)) return prio.get(n)
    let best = 0n
    for (const x of dependents.get(n)) if (pr(x) > best) best = pr(x)
    prio.set(n, best + cost.get(n))
    return prio.get(n)
  }
  names.forEach(pr)
  const freeAt = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  const done = new Map()
