    for (;;) {
      let wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let pick = null
      for (const n of names) {
        if (done.has(n)) continue
        if (!sortedDeps.get(n).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick)) pick = n
      }
      if (pick === null) break
      const f = t + cost.get(pick)
      done.set(pick, f)
      freeAt[wi] = f
      runs[wi].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
