#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { normalizeRecord, resolveRecord, UriError } from './uri.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
try {
  lines.forEach((line, i) => {
    try {
      if (args[0] === 'normalize') out.push(normalizeRecord(line))
      else out.push(resolveRecord(line))
    } catch (e) {
      if (e instanceof UriError) throw new UriError(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
cat > src/uri.js <<'EOF'
export class UriError extends Error {}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const rb = hp.lastIndexOf(']')
  const colon = hp.indexOf(':', rb + 1)
  if (colon < 0) return { userinfo, host: hp, port: undefined }
  return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
}

function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const j = input.indexOf('/', 1)
      const seg = j < 0 ? input : input.slice(0, j)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

function check(parts) {
  const { userinfo, host } = parts.auth || {}
  const list = [['path', parts.path], ['userinfo', userinfo], ['host', host], ['query', parts.query], ['fragment', parts.fragment]]
  for (const [name, v] of list) {
    if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
      throw new UriError(`the ${name} has a truncated percent-encoding`)
    }
  }
}

function finish(t) {
  // t: {scheme, authority, path, query, fragment}
  const auth = t.authority !== undefined ? splitAuthority(t.authority) : undefined
  check({ auth, path: t.path, query: t.query, fragment: t.fragment })
  const scheme = t.scheme !== undefined ? lower(t.scheme) : undefined
  let res = ''
  if (scheme !== undefined) res += scheme + ':'
  let path = t.path
  if (auth) {
    let port = auth.port
    if (port === '' || (port !== undefined && scheme !== undefined && DEFAULT_PORT[scheme] === port)) port = undefined
    res += '//'
    if (auth.userinfo !== undefined) res += pct(auth.userinfo) + '@'
    res += lower(pct(auth.host))
    if (port !== undefined) res += ':' + pct(port)
