import { readFileSync } from 'node:fs'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
const mode = args[0]

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function num(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

const policies = new Map()
const routes = new Map()
const events = []
let started = false
let lastTick = null

function parse(lines) {
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        const n = d === 'bucket' ? 5 : d === 'window' ? 4 : 3
        if (d === 'route' ? t.length < n : t.length !== n) {
          throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>'
            : d === 'window' ? 'expected window <name> <limit> <span>'
            : 'expected route <prefix> <policy>...')
        }
        if (started) throw new Fail('declarations must come before the first event')
        if (d === 'route') {
          if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
          if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
          for (const p of t.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          routes.set(t[1], t.slice(2))
        } else {
          if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
          let p
          if (d === 'bucket') {
            const capacity = num('capacity', t[2], 1)
            const refill = num('refill', t[3], 0)
            const per = num('per', t[4], 1)
            p = { type: 'bucket', capacity, refill, per }
          } else {
            const limit = num('limit', t[2], 0)
            const span = num('span', t[3], 1)
            p = { type: 'window', limit, span }
          }
          if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
          policies.set(t[1], p)
        }
      } else if (d === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) {
          throw new Fail(`tick ${t[1]} is before tick ${lastTick}`)
        }
        lastTick = tick
        started = true
        events.push({ tick, tickText: t[1], key: t[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) {
        process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  })
}

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines[lines.length - 1] === '') lines.pop()
parse(lines)

const states = new Map()
function stateFor(name, key, tick) {
  const id = name + '\0' + key
  let s = states.get(id)
  if (!s) {
    const p = policies.get(name)
    s = p.type === 'bucket' ? { scaled: p.capacity * p.per, last: tick } : { ticks: [] }
    states.set(id, s)
  }
  return s
}

function advance(p, s, tick) {
  if (p.type === 'bucket') {
    const dt = tick - s.last
    s.last = tick
    const max = p.capacity * p.per
    s.scaled += p.refill * dt
    if (s.scaled > max) s.scaled = max
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}
const allows = (p, s) => (p.type === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.type === 'bucket') s.scaled -= p.per
  else s.ticks.push(tick)
}

const out = []
const per = new Map()
let A = 0, D = 0
for (const ev of events) {
  let best = null
  for (const prefix of routes.keys()) {
    if (ev.key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
  }
  let denied = null
  if (best !== null) {
    const names = routes.get(best)
    for (const n of names) advance(policies.get(n), stateFor(n, ev.key, ev.tick), ev.tick)
    for (const n of names) {
      if (!allows(policies.get(n), stateFor(n, ev.key, ev.tick))) { denied = n; break }
    }
    if (denied === null) for (const n of names) record(policies.get(n), stateFor(n, ev.key, ev.tick), ev.tick)
  }
  const c = per.get(ev.key) || { a: 0, d: 0 }
  if (denied === null) { c.a++; A++ } else { c.d++; D++ }
  per.set(ev.key, c)
  out.push(`${ev.tickText} ${ev.key} ${denied === null ? 'allow' : 'deny ' + denied}`)
}
if (mode === 'summary') {
  out.length = 0
  for (const k of [...per.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    out.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
  }
  out.push(`total allowed=${A} denied=${D}`)
}
process.stdout.write(out.join('\n') + (out.length ? '\n' : ''))
EOF
