{"file_path":"src/scan.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const BASES = {
  x: isHex,
  b: (c) => c === '0' || c === '1',
  o: (c) => c !== undefined && c >= '0' && c <= '7',
}

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }

  // digit run with single underscores between digits; returns consumed text
  const run = (isD) => {
    let s = ''
    while (i < n) {
      if (isD(cs[i])) s += adv()
      else if (cs[i] === '_' && s !== '' && isD(cs[i - 1]) && isD(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    const sl = line
    const sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
    } else if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
    } else if (c === '/' && cs[i + 1] === '*') {
      adv()
      adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
    } else if (c === 'r' && cs[i + 1] === '"') {
      adv()
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
