import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, cur = null
  const flush = () => { if (cur) { cur.be = i; cur.se = j; out.push(cur); cur = null } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { flush(); i++; j++; continue }
    if (!cur) cur = { who, bs: i, ss: j }
    if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return out
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('error: usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) { if (l === '%%%') docs.push([]); else docs[docs.length - 1].push(l) }
  if (docs.length !== 3) fail('error: expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)

  const out = []
  let conflict = false
  const emit = (kind, ls, extra) => {
    if (mode === 'regions') out.push(extra ?? `${kind} ${ls.length}`)
    else out.push(...ls)
  }
  let pos = 0, k = 0
  const sides = [mine, theirs]
  while (k < all.length) {
    const first = all[k]
    const R0 = first.bs
    let R1 = first.be
    const group = [first]
    k++
    while (k < all.length && all[k].bs <= R1) { R1 = Math.max(R1, all[k].be); group.push(all[k]); k++ }
    if (R0 > pos) emit('stable', base.slice(pos, R0))
    pos = R1
    const rep = [null, null]
    const touched = [false, false]
    for (const w of [0, 1]) {
      const g = group.filter(c => c.who === w)
      if (!g.length) { rep[w] = base.slice(R0, R1); continue }
      touched[w] = true
      const s = Math.min(...g.map(c => c.bs)), e = Math.max(...g.map(c => c.be))
      const ss = Math.min(...g.map(c => c.ss)), se = Math.max(...g.map(c => c.se))
      rep[w] = sides[w].slice(ss - (s - R0), se + (R1 - e))
    }
    const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
    const b = base.slice(R0, R1)
    const [m, t] = rep
    if (eq(m, t)) emit(touched[0] && touched[1] ? 'both' : touched[0] ? 'mine' : 'theirs', m)
    else if (eq(m, b)) emit('theirs', t)
    else if (eq(t, b)) emit('mine', m)
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${b.length} theirs=${t.length}`)
      else if (mode === 'merge') out.push('<<<<<<< mine', ...m, '||||||| base', ...b, '=======', ...t, '>>>>>>> theirs')
      else out.push('<<<<<<< mine', ...m, '=======', ...t, '>>>>>>> theirs')
    }
  }
  if (pos < base.length) emit('stable', base.slice(pos))
  if (out.length) process.stdout.write(out.join('\n') + '\n')
  process.exitCode = conflict ? 1 : 0
}
main()
