#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scan.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const source = readFileSync(0).toString('utf8')
let tokens
try {
  tokens = scan(source)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.column}: ${e.reason}\n`)
  process.exit(2)
}

let out = ''
if (mode === 'tokens') {
  for (const t of tokens) {
    const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.value) : t.value
    out += `${t.line}:${t.column} ${t.kind} ${body}\n`
  }
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
    out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  }
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
