export class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdent = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(source) {
  const cs = Array.from(source)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  while (i < n) {
    const c = cs[i]
    const sl = line
    const sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push({ line: sl, column: sc, kind: 'rawstring', value: v })
      continue
    }
    if (isLetter(c) || c === '_') {
      let v = ''
      while (i < n && isIdent(cs[i])) v += adv()
      tokens.push({ line: sl, column: sc, kind: KEYWORDS.has(v) ? 'keyword' : 'ident', value: v })
      continue
    }
    if (isDigit(c)) {
      let v = ''
      const take = () => { v += adv() }
      const run = (ok) => {
        // digits with single underscores strictly between digits; false if none
        if (!ok(cs[i])) return false
        take()
        while (i < n && (ok(cs[i]) || (cs[i] === '_' && ok(cs[i + 1])))) take()
        return true
      }
      let bad = false
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        take(); take()
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        const e = cs[i]
        if ((e === 'e' || e === 'E') && (isDigit(cs[i + 1]) || ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])))) {
          take()
          if (!isDigit(cs[i])) take()
          run(isDigit)
        }
      }
      if (bad || isIdent(cs[i])) {
        while (i < n && isIdent(cs[i])) take()
        throw new ScanError(sl, sc, `invalid number ${v}`)
      }
      tokens.push({ line: sl, column: sc, kind: 'number', value: v })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line
        const ec = col
        const d = adv()
        if (d === '"') break
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        if (d !== '\\') { v += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
          v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16))
          advN(2)
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          v += String.fromCodePoint(cp)
          advN(j + 1 - i)
        } else throw bad()
      }
      tokens.push({ line: sl, column: sc, kind: 'string', value: v })
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { advN(2); tokens.push({ line: sl, column: sc, kind: 'punct', value: two }); continue }
    if (PUNCT1.has(c)) { adv(); tokens.push({ line: sl, column: sc, kind: 'punct', value: c }); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
